#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // x == j (fast), y == i (slow)
    Var x("x"), y("y");
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    Expr n_expr = cast<num_t>(n);
    init_u(x, y) = cast<num_t>(y + n - x) / n_expr;

    // Simple but effective schedule: vectorize in x, parallelize in y.
    Target target = get_host_target();
    const int vec_width = natural_vector_size<num_t>(target);
    init_u
        .vectorize(x, vec_width)
        .parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * In the original PolyBench-style code, p and q are N×N scratch arrays
 * used only as 1D temporaries along a single spatial dimension at a time
 * (Thomas algorithm). Keeping them as full 2D arrays is unnecessary:
 * per-line 1D temporaries suffice. Here we switch to 1D temporaries inside
 * the kernel, which:
 *   - reduces scratch storage from O(N^2) to O(N),
 *   - improves cache locality,
 *   - preserves the numerical scheme exactly (u and v are unchanged).
 *
 * Due to the 1D recurrences along j, this kernel is expressed with
 * explicit C++ loops, following the recommendation to keep such
 * loop-carried dependencies outside Halide Funcs.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v) {
    // Discretization and ADI coefficients (constant over i, j, t)
    const num_t DX   = num_t(1.0) / num_t(n);
    const num_t DY   = num_t(1.0) / num_t(n);
    const num_t DT   = num_t(1.0) / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = num_t(1.0) + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = num_t(1.0) + mul2;
    const num_t f = d;

    // Hoisted combinations used in the inner loops.
    const num_t one_plus_2d = num_t(1.0) + num_t(2.0) * d;
    const num_t one_plus_2a = num_t(1.0) + num_t(2.0) * a;

    // 1D temporaries along the j-dimension for the Thomas algorithm.
    // We use Halide::Buffer here for consistency with the rest of the code,
    // but they are accessed like simple 1D arrays: tmp(j).
    Halide::Buffer<num_t, 1> p_line(n);
    Halide::Buffer<num_t, 1> q_line(n);

    // Time-stepping loop (sequential in t)
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep
        //
        // For each fixed interior "column" index i (1 .. n-2), we solve
        // a tridiagonal system along j to obtain v(:, i), with boundary
        // conditions v[0][i] = v[n-1][i] = 1.
        //
        // Original C, in terms of C indices u[i][j], v[i][j]:
        //
        //   for (i = 1; i < n - 1; i++) {
        //     v[0][i] = 1.0;
        //     p[i][0] = 0.0;
        //     q[i][0] = v[0][i];
        //     for (j = 1; j < n - 1; j++) {
        //       denom = a * p[i][j-1] + b;
        //       p[i][j] = -c / denom;
        //       q[i][j] =
        //         (-d * u[j-1][i]
        //          + (1 + 2*d) * u[j][i]
        //          - f * u[j+1][i]
        //          - a * q[i][j-1]) /
        //         (a * p[i][j-1] + b);
        //     }
        //     v[n-1][i] = 1.0;
        //     for (j = n - 2; j >= 1; j--) {
        //       v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
        //     }
        //   }
        //
        // Remember: Buffer mapping is A(j, i) == C A[i][j].
        // ------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // Boundary conditions at "row" j = 0 and j = n-1 for this i.
            // v[0][i] -> v(i, 0)
            v(i, 0) = num_t(1.0);

            // Initialize tridiagonal forward-sweep coefficients.
            // p[i][0] = 0.0; q[i][0] = v[0][i]
            p_line(0) = num_t(0.0);
            q_line(0) = v(i, 0);

            // Forward sweep along j = 1 .. n-2 (Thomas algorithm).
            for (int j = 1; j < n - 1; j++) {
                const num_t denom = a * p_line(j - 1) + b;
                const num_t p_j   = -c / denom;
                p_line(j) = p_j;

                const num_t num =
                    -d * u(i - 1, j) +
                    one_plus_2d * u(i,     j) -
                    f * u(i + 1, j) -
                    a * q_line(j - 1);

                q_line(j) = num / denom;
            }

            // Right boundary: v[n-1][i] = 1.0  -> v(i, n-1)
            v(i, n - 1) = num_t(1.0);

            // Back substitution along j = n-2 .. 1:
            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p_line(j) * v(i, j + 1) + q_line(j);
            }
        }

        // ------------------------------------------------------------
        // Row sweep
        //
        // For each fixed interior index i (1 .. n-2), we solve another
        // tridiagonal system along j to update u(:, i) using v, with
        // boundary conditions u[i][0] = u[i][n-1] = 1.
        //
        // Original C (again in terms of C indices u[i][j], v[i][j]):
        //
        //   for (i = 1; i < n - 1; i++) {
        //     u[i][0] = 1.0;
        //     p[i][0] = 0.0;
        //     q[i][0] = u[i][0];
        //     for (j = 1; j < n - 1; j++) {
        //       denom = d * p[i][j-1] + e;
        //       p[i][j] = -f / denom;
        //       q[i][j] =
        //         (-a * v[i-1][j]
        //          + (1 + 2*a) * v[i][j]
        //          - c * v[i+1][j]
        //          - d * q[i][j-1]) /
        //         (d * p[i][j-1] + e);
        //     }
        //     u[i][n-1] = 1.0;
        //     for (j = n - 2; j >= 1; j--) {
        //       u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
        //     }
        //   }
        //
        // With Buffer mapping A(j, i) == C A[i][j], we keep the same
        // access pattern as in the original kernel but use 1D scratch.
        // ------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // Boundary conditions for this "row" i:
            // u[i][0]   -> u(0, i)
            // u[i][n-1] -> u(n-1, i)
            u(0,     i) = num_t(1.0);
            u(n - 1, i) = num_t(1.0);

            // Initialize forward-sweep coefficients for this row.
            // p[i][0] = 0.0; q[i][0] = u[i][0];
            p_line(0) = num_t(0.0);
            q_line(0) = u(0, i);

            // Forward sweep along j = 1 .. n-2.
            for (int j = 1; j < n - 1; j++) {
                const num_t denom = d * p_line(j - 1) + e;
                const num_t p_j   = -f / denom;
                p_line(j) = p_j;

                const num_t num =
                    -a * v(j,     i - 1) +
                    one_plus_2a * v(j,     i) -
                    c * v(j,     i + 1) -
                    d * q_line(j - 1);

                q_line(j) = num / denom;
            }

            // Back substitution along j = n-2 .. 1.
            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p_line(j) * u(j + 1, i) + q_line(j);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);

    // Initialize u; v is a scratch array.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
