 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i),
 * i.e. Buffer(x = j, y = i) corresponds to C u[i][j].
 *
 * This is implemented as a small Halide pipeline with
 * simple vectorization and parallelization.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // x == column index j (fast), y == row index i (slow)
    Var x("x"), y("y");
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple schedule: vectorize along the contiguous x dimension
    // and parallelize across rows.
    //
    // Note: the vector width is fixed (16). Halide will handle
    // non-multiple-of-16 extents by generating a scalar tail.
    init_u
        .vectorize(x, 16)
        .parallel(y);

    // JIT-compile and realize directly into the provided Buffer.
    init_u.realize(u);
}

