 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i):
 *   - Buffer(x, y) corresponds to C A[y][x].
 *
 * This optimized version keeps the numerical scheme identical, but:
 *   - Hoists all time-invariant coefficients out of inner loops.
 *   - Uses 1D temporaries p_line and q_line for each 1D solve
 *     instead of full N×N p and q arrays, improving locality and
 *     reducing memory footprint.
 *   - Exploits parallelism across independent lines (i) using
 *     OpenMP pragmas when compiled with -fopenmp (otherwise they
 *     are ignored and execution remains serial).
 *
 * Note: The p and q Buffers are still allocated by the caller to
 *       preserve the original interface, but are no longer used
 *       for computation—they were scratch only.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> /*p*/,
                       Halide::Buffer<num_t, 2> /*q*/) {
    // ------------------------------------------------------------------
    // Precompute scalar coefficients (invariant across i, j, t).
    // ------------------------------------------------------------------
    const num_t DX   = num_t(1.0) / num_t(n);
    const num_t DY   = num_t(1.0) / num_t(n);
    const num_t DT   = num_t(1.0) / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = num_t(1.0) + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = num_t(1.0) + mul2;
    const num_t f = d;

    // Hoisted combinations used in inner loops.
    const num_t one_plus_2d = num_t(1.0) + num_t(2.0) * d;
    const num_t one_plus_2a = num_t(1.0) + num_t(2.0) * a;

    // ------------------------------------------------------------------
    // Time-stepping loop.
    //
    // The time dimension is inherently sequential: each step reads
    // and writes u and v and depends on the result of the previous
    // step.
    // ------------------------------------------------------------------
    for (int t = 1; t <= tsteps; t++) {

        // ==============================================================
        // 1) Column sweep
        //
        // For each column index "i" (interpreted as C column index,
        // i.e. Buffer x-coordinate), we solve a 1D tridiagonal system
        // along the vertical direction "j" (Buffer y-coordinate) to
        // update v(*, i).
        //
        // Original C logic (in terms of C u[row][col], v[row][col]):
        //   for (i = 1; i < n-1; i++) {
        //     v[0][i] = 1;
        //     p[i][0] = 0;
        //     q[i][0] = v[0][i];
        //     for (j = 1; j < n-1; j++) {
        //       denom = a * p[i][j-1] + b;
        //       p[i][j] = -c / denom;
        //       q[i][j] = (-d*u[j-1][i] + (1+2d)*u[j][i] - f*u[j+1][i]
        //                  - a*q[i][j-1]) / denom;
        //     }
        //     v[n-1][i] = 1;
        //     for (j = n-2; j >= 1; j--) {
        //       v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
        //     }
        //   }
