        //   - v[0][i]   -> v(i, 0)
        //   - v[j][i]   -> v(i, j)
        //   - u[j][i]   -> u(i, j)
        //   - u[j-1][i] -> u(i, j-1)
        //   - u[j+1][i] -> u(i, j+1)
        // etc.
