#ifdef _OPENMP
#pragma omp parallel
#endif
        {
            // 1D temporary storage for this worker (thread).
            std::vector<num_t> p_line(n);
            std::vector<num_t> q_line(n);

#ifdef _OPENMP
#pragma omp for schedule(static)
#endif
