                // Left boundary in this column: v[0][i] = 1;
                v(i, 0) = num_t(1.0);

                // Initialize tridiagonal forward-sweep coefficients.
                // p[i][0] = 0; q[i][0] = v[0][i];
                p_line[0] = num_t(0.0);
                q_line[0] = v(i, 0);

