                    //   (-d * u[j-1][i]
                    //    + (1 + 2*d) * u[j][i]
                    //    - f * u[j+1][i]
                    //    - a * q[i][j-1]) /
                    //   (a * p[i][j-1] + b);
                    num_t num =
                        -d * u(i, j - 1) +
                        one_plus_2d * u(i, j) -
                        f * u(i, j + 1) -
                        a * q_line[j - 1];

                    q_line[j] = num / denom;
                }

                // Right boundary: v[n-1][i] = 1;
                v(i, n - 1) = num_t(1.0);

                // Back-substitution along j = n-2 .. 1:
                for (int j = n - 2; j >= 1; j--) {
