            // 2) Row sweep
            //
            // For each interior row index "i" (now interpreted as C row
            // index, i.e. Buffer y-coordinate), we solve a tridiagonal
            // system along the horizontal direction "j" (Buffer x) to
            // update u(i, *) using v.
            //
            // Original C (in terms of C u[row][col], v[row][col]):
            //   for (i = 1; i < n-1; i++) {
            //     u[i][0] = 1;
            //     p[i][0] = 0;
            //     q[i][0] = u[i][0];
            //     for (j = 1; j < n-1; j++) {
            //       denom = d * p[i][j-1] + e;
            //       p[i][j] = -f / denom;
            //       q[i][j] = (-a*v[i-1][j] + (1+2a)*v[i][j] - c*v[i+1][j]
