            //   - u[i][0]   -> u(0, i)
            //   - u[i][j]   -> u(j, i)
            //   - v[i-1][j] -> v(j, i-1)
            //   - v[i+1][j] -> v(j, i+1)
            //
            // Again we use 1D per-row temporaries p_line, q_line.
            // ==========================================================
#ifdef _OPENMP
#pragma omp for schedule(static)
#endif
            for (int i = 1; i < n - 1; i++) {
                // Left boundary in this row: u[i][0] = 1;
                u(0, i) = num_t(1.0);

                // Initialize tridiagonal coefficients.
                // p[i][0] = 0; q[i][0] = u[i][0];
                p_line[0] = num_t(0.0);
                q_line[0] = u(0, i);

                // Forward sweep along j = 1 .. n-2
                for (int j = 1; j < n - 1; j++) {
                    // denom = d * p[i][j-1] + e;
                    num_t denom = d * p_line[j - 1] + e;

                    // p[i][j] = -f / denom;
                    p_line[j] = -f / denom;

                    // q[i][j] =
                    //   (-a * v[i-1][j]
                    //    + (1 + 2*a) * v[i][j]
                    //    - c * v[i+1][j]
                    //    - d * q[i][j-1]) /
                    //   (d * p[i][j-1] + e);
                    num_t num =
                        -a * v(j, i - 1) +
                        one_plus_2a * v(j, i) -
                        c * v(j, i + 1) -
                        d * q_line[j - 1];

                    q_line[j] = num / denom;
                }

                // Right boundary: u[i][n-1] = 1;
                u(n - 1, i) = num_t(1.0);

                // Back-substitution along j = n-2 .. 1:
                for (int j = n - 2; j >= 1; j--) {
                    // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                    u(j, i) = p_line[j] * u(j + 1, i) + q_line[j];
                }
            } // end row sweep
        }     // end parallel region
    }         // end time loop
}

