#include <iostream>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    init_u.realize(u);
}

/*
 * Optimized ADI kernel using Halide.
 *
 * Semantics match the original kernel_adi: given u at time t, it performs
 * tsteps ADI steps in-place on u, using v, p, q as scratch (their final
 * values are not observed).
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i), i.e.
 *   C A[i][j]  ==  Halide buffer A(x = j, y = i).
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> /*p*/,
                       Halide::Buffer<num_t, 2> /*q*/) {
    // ------------------------------------------------------------------
    // Scalar coefficients (identical to original code, but hoisted).
    // ------------------------------------------------------------------
    const num_t DX   = num_t(1.0) / num_t(n);
    const num_t DY   = num_t(1.0) / num_t(n);
    const num_t DT   = num_t(1.0) / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = num_t(1.0) + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = num_t(1.0) + mul2;
    const num_t f = d;

    const num_t one_plus_2d = num_t(1.0) + num_t(2.0) * d;
    const num_t one_plus_2a = num_t(1.0) + num_t(2.0) * a;

    // ------------------------------------------------------------------
    // Halide pipeline for ONE time step:
    //
    //   u_in  --(column sweep)--> v_step
    //   v_step --(row sweep)--> u_new
    //
    // We run this pipeline tsteps times from C++, using double buffering
    // for u. This keeps the time loop explicit on the host (simple and
    // safe) while Halide handles the heavy 2D computation per step.
    // ------------------------------------------------------------------

    Var x("x"), y("y"); // x == j (column), y == i (row)

    // Current state input for a single time step.
    ImageParam u_in(type_of<num_t>(), 2, "u_in");

    // Parameters for sizes and coefficients.
    Param<int> n_param("n_param");
    n_param.set(n);

    Param<num_t> a_p("a_p"), b_p("b_p"), c_p("c_p");
    Param<num_t> d_p("d_p"), e_p("e_p"), f_p("f_p");
    Param<num_t> one_plus_2d_p("one_plus_2d_p");
    Param<num_t> one_plus_2a_p("one_plus_2a_p");

    a_p.set(a);
    b_p.set(b);
    c_p.set(c);
    d_p.set(d);
    e_p.set(e);
    f_p.set(f);
    one_plus_2d_p.set(one_plus_2d);
    one_plus_2a_p.set(one_plus_2a);

    // ------------------------------------------------------------------
    // Column sweep: build p_col, q_col, v_step from u_in.
    // All arrays are in (x,y) = (j,i) coordinates.
    // Only interior rows y in [1, n-2] are updated, matching the original
    // loop over i = 1 .. n-2. Boundary rows y = 0,n-1 are copied.
    // ------------------------------------------------------------------
    Func p_col("p_col"), q_col("q_col"), v_step("v_step");

    // Base definitions:
    //   - p_col, q_col start from zero everywhere (they are fully
    //     overwritten on the interior).
    //   - v_step starts as a copy of u_in; then interior column
    //     boundaries at j=0 and j=n-1 are overridden to 1.0, and
    //     interior points are filled via backward substitution.
    p_col(x, y) = cast<num_t>(0);
    q_col(x, y) = cast<num_t>(0);
    v_step(x, y) = u_in(x, y);

    // Boundary conditions for v_step and initial p_col, q_col at j = 0.
    // Only for interior rows 1 .. n-2.
    RDom ry(1, n_param - 2, "ry"); // y in [1, n-2]

    // v[0][i] = 1.0; v[n-1][i] = 1.0;
    v_step(0, ry)            = cast<num_t>(1.0);
    v_step(n_param - 1, ry)  = cast<num_t>(1.0);

    // p[i][0] = 0.0; q[i][0] = v[0][i];
    p_col(0, ry) = cast<num_t>(0.0);
    q_col(0, ry) = v_step(0, ry);

    // Forward sweep along j = 1 .. n-2 for interior rows y = 1 .. n-2.
    // This is the Thomas algorithm along the j dimension.
    RDom rcf(1, n_param - 2,   // j in [1, n-2]
             1, n_param - 2,   // i in [1, n-2]
             "rcf");

    RVar rcf_x = rcf.x; // j
    RVar rcf_y = rcf.y; // i

    Expr j_f = rcf.x;
    Expr i_f = rcf.y;

    Expr denom_c = a_p * p_col(j_f - 1, i_f) + b_p;
    p_col(j_f, i_f) = -c_p / denom_c;

    Expr num_c = -d_p * u_in(j_f - 1, i_f) +
                 one_plus_2d_p * u_in(j_f, i_f) -
                 f_p * u_in(j_f + 1, i_f) -
                 a_p * q_col(j_f - 1, i_f);

    q_col(j_f, i_f) = num_c / denom_c;

    // Backward substitution along j = n-2 .. 1 for interior rows.
    // We iterate rcb.x = 1..n-2, and map to j_b = n-1 - rcb.x, which
    // runs j_b = n-2 .. 1. Each step depends on v_step(j_b+1, i_b),
    // which has already been computed.
    RDom rcb(1, n_param - 2,
             1, n_param - 2,
             "rcb");

    RVar rcb_x = rcb.x;
    RVar rcb_y = rcb.y;

    Expr j_b = n_param - 1 - rcb.x; // j_b: n-2 .. 1
    Expr i_b = rcb.y;

    v_step(j_b, i_b) = p_col(j_b, i_b) * v_step(j_b + 1, i_b) + q_col(j_b, i_b);

    // ------------------------------------------------------------------
    // Row sweep: build u_new from v_step.
    //
    // Only interior rows y in [1, n-2] are updated, matching the original
    // row sweep. For those rows, we impose:
    //   u[i][0]   = 1.0,  u[i][n-1] = 1.0,
    // and then solve tridiagonal systems along j for 1..n-2 via p_row,q_row.
    //
    // Boundary rows y = 0,n-1 are left unchanged (copied from u_in).
    // ------------------------------------------------------------------
    Func p_row("p_row"), q_row("q_row"), u_new("u_new");

    // Start from previous u_in everywhere; boundaries for interior
    // rows are then overridden.
    u_new(x, y) = u_in(x, y);
    p_row(x, y) = cast<num_t>(0);
    q_row(x, y) = cast<num_t>(0);

    RDom ry2(1, n_param - 2, "ry2"); // interior rows y = 1..n-2

    // u[i][0] = 1.0; u[i][n-1] = 1.0;
    u_new(0,           ry2) = cast<num_t>(1.0);
    u_new(n_param - 1, ry2) = cast<num_t>(1.0);

    // p[i][0] = 0.0; q[i][0] = u[i][0] (= 1.0);
    p_row(0, ry2) = cast<num_t>(0.0);
    q_row(0, ry2) = u_new(0, ry2);

    // Forward sweep along j = 1 .. n-2 for interior rows.
    RDom rrf(1, n_param - 2,
             1, n_param - 2,
             "rrf");

    RVar rrf_x = rrf.x;
    RVar rrf_y = rrf.y;

    Expr j_rf = rrf.x;
    Expr i_rf = rrf.y;

    Expr denom_r = d_p * p_row(j_rf - 1, i_rf) + e_p;
    p_row(j_rf, i_rf) = -f_p / denom_r;

    Expr num_r = -a_p * v_step(j_rf, i_rf - 1) +
                 one_plus_2a_p * v_step(j_rf, i_rf) -
                 c_p * v_step(j_rf, i_rf + 1) -
                 d_p * q_row(j_rf - 1, i_rf);

    q_row(j_rf, i_rf) = num_r / denom_r;

    // Backward substitution along j = n-2 .. 1 for interior rows.
    RDom rrb(1, n_param - 2,
             1, n_param - 2,
             "rrb");

    RVar rrb_x = rrb.x;
    RVar rrb_y = rrb.y;

    Expr j_rb = n_param - 1 - rrb.x; // j_rb: n-2 .. 1
    Expr i_rb = rrb.y;

    u_new(j_rb, i_rb) = p_row(j_rb, i_rb) * u_new(j_rb + 1, i_rb) + q_row(j_rb, i_rb);

    // ------------------------------------------------------------------
    // Scheduling
    //
    // The recurrences are along j (x); different rows y are independent.
    // We parallelize across rows y for the update stages, leaving the
    // 1D Thomas recurrences along x sequential.
    //
    // This matches the "parallelize over independent lines" strategy
    // outlined in the ADI models: outer parallelism in y (i), inner
    // sequential sweeps in x (j).
    // ------------------------------------------------------------------
    Target target = get_host_target();

    // Compute all intermediate Funcs at root to make the schedule explicit.
    p_col.compute_root();
    q_col.compute_root();
    v_step.compute_root();
    p_row.compute_root();
    q_row.compute_root();
    u_new.compute_root();

    // Parallelize column forward sweep across rows (rcf_y).
    p_col.update()
         .reorder(rcf_y, rcf_x)    // for (i) { for (j) { ... } }
         .parallel(rcf_y);
    q_col.update()
         .reorder(rcf_y, rcf_x)
         .parallel(rcf_y);

    // Parallelize column backward substitution across rows (rcb_y).
    // v_step has two update stages: 0 = boundary fill, 1 = back-substitution.
    v_step.update(1)
          .reorder(rcb_y, rcb_x)
          .parallel(rcb_y);

    // Parallelize row forward sweep across rows (rrf_y).
    p_row.update()
         .reorder(rrf_y, rrf_x)
         .parallel(rrf_y);
    q_row.update()
         .reorder(rrf_y, rrf_x)
         .parallel(rrf_y);

    // u_new has three update stages:
    //   0: u_new(0, ry2)   = 1.0;
    //   1: u_new(n-1, ry2) = 1.0;
    //   2: backward substitution.
    // We parallelize the backward substitution across rows.
    u_new.update(2)
         .reorder(rrb_y, rrb_x)
         .parallel(rrb_y);

    // Mild vectorization of the pure definitions over x (j). The heavy
    // work is in the RDom updates; those remain scalar along x by design
    // (due to the recurrences).
    const int vec_width = 8; // reasonable default for modern x86
    v_step.vectorize(x, vec_width);
    u_new.vectorize(x, vec_width);

    // Build the one-step pipeline.
    Pipeline step_pipeline(u_new);
    step_pipeline.compile_jit(target);

    // ------------------------------------------------------------------
    // Host-level time loop with double buffering for u.
    //
    // We alternate between:
    //   - reading from the current u_curr,
    //   - writing the next state into u_next_buf (we reuse the storage
    //     of the input buffer v as scratch to avoid extra allocations).
    //
    // At the end, if the final state lives in the scratch buffer,
    // we copy it back into the original u buffer once.
    // ------------------------------------------------------------------
    Halide::Buffer<num_t, 2> u_curr = u;  // current solution
    Halide::Buffer<num_t, 2> u_next_buf = v; // reuse v's storage as scratch

    for (int t = 1; t <= tsteps; t++) {
        // Bind current state and realize one ADI step.
        u_in.set(u_curr);
        step_pipeline.realize(u_next_buf);

        // Swap current and next for the next iteration.
        std::swap(u_curr, u_next_buf);
    }

    // After tsteps steps, u_curr holds the final solution. If it does not
    // alias the original u buffer, copy it back once.
    if (u_curr.data() != u.data()) {
        for (int yi = 0; yi < n; yi++) {
            for (int xj = 0; xj < n; xj++) {
                u(xj, yi) = u_curr(xj, yi);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
