#include <chrono>
#include <iomanip>
#include <iostream>
#include <vector>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * Here we keep the mapping used in the original file:
 *   C array u[i][j]  <->  Halide::Buffer u(j, i)
 * i.e. Buffer dimension 0 is j (fast), dimension 1 is i (slow).
 *
 * We implement this initialization as a small Halide pipeline and
 * schedule it to exploit parallelism and vectorization.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // x == j (fast), y == i (slow)
    Var x("x"), y("y");
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    // Note: n is an int; it is implicitly lifted to an Expr.
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple CPU schedule:
    // - vectorize across the fast dimension x
    // - parallelize over scanlines in y
    Target t = get_host_target();
    int vec_width = natural_vector_size<u.type(), 0>(t); // natural SIMD width for num_t
    if (vec_width > 0) {
        init_u.vectorize(x, vec_width);
    }
    init_u.parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel operating on Halide::Buffer.
 *
 * Signature corresponds to the original C kernel:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * C array A[i][j] is mapped to Buffer A(j, i), i.e.,
 *   A_C[i][j] == A_buf(j, i).
 *
 * The ADI scheme consists of:
 *   - A "column" sweep, which in this translation uses neighbors in
 *     the first coordinate (matching the existing code),
 *   - followed by a "row" sweep.
 *
 * IMPORTANT: There are strong loop-carried dependencies along j in
 * each sweep (Thomas algorithm for tridiagonal solves). These cannot
 * be expressed as legal Halide update definitions (they would require
 * reading A(i, j-1) while writing A(i, j)), so we keep the sweeps as
 * explicit C++ loops over Halide::Buffer data, as recommended for
 * such patterns.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // --------------------------------------------------------------------
    // Scalar coefficients (identical to the original code, but with some
    // precomputed combinations to reduce flops in the inner loops).
    // --------------------------------------------------------------------
    const num_t DX   = num_t(1.0) / num_t(n);
    const num_t DY   = num_t(1.0) / num_t(n);
    const num_t DT   = num_t(1.0) / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = num_t(1.0) + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = num_t(1.0) + mul2;
    const num_t f = d;

    // Frequently used combinations: 1 + 2*d and 1 + 2*a
    const num_t one_plus_2d = num_t(1.0) + num_t(2.0) * d;
    const num_t one_plus_2a = num_t(1.0) + num_t(2.0) * a;

    const int n_minus_1 = n - 1;

    // --------------------------------------------------------------------
    // We keep the 2D Buffers p and q for compatibility with the original
    // interface and semantics, but inside each sweep we operate on a
    // contiguous “line” p_line[j], q_line[j] corresponding to a fixed
    // second index (i). This reduces repeated index arithmetic and
    // lets the compiler better optimize memory access along j.
    //
    //   For a fixed i, &p(0, i) points to the contiguous row
    //   { p(0, i), p(1, i), ..., p(n-1, i) }.
    //
    //   Similarly for q(0, i).
    // --------------------------------------------------------------------

    // Time-stepping loop is inherently sequential (state at step t+1
    // depends on the fully updated state at step t).
    for (int t = 1; t <= tsteps; t++) {

        // ============================================================
        // 1) "Column" sweep
        //
        // The existing translation sweeps along j but uses neighbors
        // in the first index (x) of u and v:
        //
        //   p(j, i), q(j, i) depend on p(j-1, i), q(j-1, i),
        //   and on u(i-1, j), u(i, j), u(i+1, j).
        //
        // Different values of i are independent, but since we are not
        // using a threading library here, we exploit only scalar
        // optimizations and locality improvements.
        // ============================================================
        for (int i = 1; i < n_minus_1; i++) {
            // For this fixed i, get contiguous slices of p and q.
            num_t *p_line = &p(0, i); // p_line[j] == p(j, i)
            num_t *q_line = &q(0, i); // q_line[j] == q(j, i)

            // v[0][i] = 1.0;
            v(i, 0) = num_t(1.0);

            // p[i][0] = 0.0;
            p_line[0] = num_t(0.0);

            // q[i][0] = v[0][i];
            q_line[0] = v(i, 0);

            // Forward sweep along j (1 .. n-2)
            for (int j = 1; j < n_minus_1; j++) {
                // denom = a * p[i][j-1] + b;
                const num_t denom = a * p_line[j - 1] + b;

                // p[i][j] = -c / denom;
                p_line[j] = -c / denom;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) / denom;
                //
                // Mapping back to Buffers (keeping the original code's
                // semantics):
                //   u[j][i-1] <-> u(i - 1, j)
                //   u[j][i]   <-> u(i,     j)
                //   u[j][i+1] <-> u(i + 1, j)
                //   q[i][j-1] <-> q_line[j - 1]
                const num_t num =
                    -d * u(i - 1, j) +
                    one_plus_2d * u(i, j) -
                    f * u(i + 1, j) -
                    a * q_line[j - 1];

                q_line[j] = num / denom;
            }

            // v[n-1][i] = 1.0;
            v(i, n_minus_1) = num_t(1.0);

            // Back substitution along j (descending: n-2 .. 1)
            for (int j = n_minus_1 - 1; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p_line[j] * v(i, j + 1) + q_line[j];
            }
        }

        // ============================================================
        // 2) "Row" sweep
        //
        // Now we update u using v. Again, there are recurrences along
        // j through p(i,j) and q(i,j), but different i values are
        // independent.
        // ============================================================
        for (int i = 1; i < n_minus_1; i++) {
            // Reuse the same contiguous slices p_line and q_line
            // for this row index i.
            num_t *p_line = &p(0, i); // p_line[j] == p(j, i)
            num_t *q_line = &q(0, i); // q_line[j] == q(j, i)

            // u[i][0] = 1.0;
            u(0, i) = num_t(1.0);

            // p[i][0] = 0.0;
            p_line[0] = num_t(0.0);

            // q[i][0] = u[i][0];
            q_line[0] = u(0, i);

            // Forward sweep along j (1 .. n-2)
            for (int j = 1; j < n_minus_1; j++) {
                // denom = d * p[i][j-1] + e;
                const num_t denom = d * p_line[j - 1] + e;

                // p[i][j] = -f / denom;
                p_line[j] = -f / denom;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) / denom;
                //
                // Mapping to Buffers:
                //   v[i-1][j] <-> v(j, i - 1)
                //   v[i][j]   <-> v(j, i)
                //   v[i+1][j] <-> v(j, i + 1)
                //   q[i][j-1] <-> q_line[j - 1]
                const num_t num =
                    -a * v(j, i - 1) +
                    one_plus_2a * v(j, i) -
                    c * v(j, i + 1) -
                    d * q_line[j - 1];

                q_line[j] = num / denom;
            }

            // u[i][n-1] = 1.0;
            u(n_minus_1, i) = num_t(1.0);

            // Back substitution along j (descending: n-2 .. 1)
            for (int j = n_minus_1 - 1; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p_line[j] * u(j + 1, i) + q_line[j];
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    // Recall: C u[i][j] == Buffer u(j, i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
